"use client"

import { Pencil, Save, Undo2 } from "lucide-react"
import * as React from "react"
import { useMemo, useState } from "react"
import ReactMarkdown from "react-markdown"

import {
  MessageArtifact,
  MessageCode,
  MessageReasoning,
  MessageToolCall,
  MessageToolCalls,
  type MessageArtifactData,
  type MessageCodeBlockData,
  type MessageToolCallData,
} from "@/components/ui/message-parts"
import { cn } from "@/lib/utils"

export type PatternHandler = {
  pattern: RegExp
  render: (match: RegExpExecArray) => React.ReactNode
}

export type ActionButton = {
  id: string
  icon: React.ReactNode
  onClick: () => void
  title?: string
  className?: string
  position?: "inside" | "outside"
}

export type MessageProps = {
  content: string
  sender: "user" | "assistant"
  actionButtons?: ActionButton[]
  editable?: boolean
  onEdit?: (content: string) => void
  patternHandlers?: PatternHandler[]
  className?: string
  contentClassName?: string
  /** Explicit reasoning (overrides `<think>` parse when set). */
  reasoning?: string | null
  reasoningDefaultOpen?: boolean
  /** Shown as “Thought for N seconds” when set. */
  reasoningDuration?: number
  tools?: MessageToolCallData[]
  codeBlocks?: MessageCodeBlockData[]
  artifacts?: MessageArtifactData[]
}

const THINK_TAG_REGEX = /<think>([\s\S]*?)<\/think>/i
const USER_PREVIEW_MAX_WORDS = 80

function previewUserMessageText(text: string, maxWords: number) {
  const words = text.trim().split(/\s+/)
  if (words.length <= maxWords) {
    return { preview: text, remainder: "" }
  }
  return {
    preview: words.slice(0, maxWords).join(" ") + "…",
    remainder: words.slice(maxWords).join(" "),
  }
}

export function Message({
  content,
  sender,
  actionButtons = [],
  editable = false,
  onEdit,
  patternHandlers = [],
  className,
  contentClassName,
  reasoning: reasoningProp,
  reasoningDefaultOpen = false,
  reasoningDuration,
  tools = [],
  codeBlocks = [],
  artifacts = [],
}: MessageProps) {
  const [isEditing, setIsEditing] = useState(false)
  const [editedContent, setEditedContent] = useState(content)
  const [longPromptExpanded, setLongPromptExpanded] = useState(false)

  const { reasoning, displayContent } = useMemo(() => {
    if (reasoningProp != null) {
      return { reasoning: reasoningProp || null, displayContent: content }
    }
    const match = THINK_TAG_REGEX.exec(content)
    if (!match) return { reasoning: null, displayContent: content }
    return {
      reasoning: match[1].trim(),
      displayContent: content.replace(THINK_TAG_REGEX, "").trim(),
    }
  }, [content, reasoningProp])

  React.useEffect(() => {
    setEditedContent(content)
  }, [content])

  const processContent = React.useCallback(
    (text: string): React.ReactNode => {
      if (!text || patternHandlers.length === 0) return text
      const segments: React.ReactNode[] = []
      let cursor = 0
      while (cursor < text.length) {
        let earliest: {
          handler: PatternHandler
          match: RegExpExecArray
          index: number
        } | null = null
        for (const handler of patternHandlers) {
          handler.pattern.lastIndex = cursor
          const match = handler.pattern.exec(text)
          if (match && (!earliest || match.index < earliest.index)) {
            earliest = { handler, match, index: match.index }
          }
        }
        if (!earliest) {
          segments.push(text.slice(cursor))
          break
        }
        if (earliest.index > cursor) {
          segments.push(text.slice(cursor, earliest.index))
        }
        let rendered: React.ReactNode
        try {
          rendered = earliest.handler.render(earliest.match) ?? earliest.match[0]
        } catch {
          rendered = earliest.match[0]
        }
        segments.push(
          <React.Fragment key={`${earliest.index}-${cursor}`}>
            {rendered}
          </React.Fragment>
        )
        cursor = earliest.index + earliest.match[0].length
      }
      return <>{segments}</>
    },
    [patternHandlers]
  )

  const markdownComponents = useMemo(() => {
    if (patternHandlers.length === 0) return undefined
    const processChildren = (children: React.ReactNode) => {
      if (Array.isArray(children)) {
        return children.map((c, index) =>
          typeof c === "string" ? (
            <React.Fragment key={index}>{processContent(c)}</React.Fragment>
          ) : (
            <React.Fragment key={index}>{c}</React.Fragment>
          )
        )
      }
      return typeof children === "string" ? processContent(children) : children
    }
    return {
      p: ({ children }: { children?: React.ReactNode }) => (
        <p className="mb-3 last:mb-0">{processChildren(children)}</p>
      ),
      li: ({ children }: { children?: React.ReactNode }) => (
        <li>{processChildren(children)}</li>
      ),
    }
  }, [patternHandlers, processContent])

  const { insideButtons, outsideButtons } = useMemo(() => {
    const inside = actionButtons.filter((btn) => btn.position !== "outside")
    const outside = actionButtons.filter((btn) => btn.position === "outside")
    return { insideButtons: inside, outsideButtons: outside }
  }, [actionButtons])

  const handleSaveEdit = () => {
    setIsEditing(false)
    if (onEdit && editedContent !== content) onEdit(editedContent)
  }

  if (sender === "user") {
    if (isEditing) {
      return (
        <div
          className={cn("mb-4 flex w-full justify-end", className)}
        >
          <div className="w-full max-w-[70%] rounded-[18px] border border-border bg-muted px-4 py-2.5">
            <textarea
              value={editedContent}
              onChange={(e) => setEditedContent(e.target.value)}
              onKeyDown={(e) => {
                if (e.key === "Enter" && (e.ctrlKey || e.metaKey)) {
                  handleSaveEdit()
                } else if (e.key === "Escape") {
                  setIsEditing(false)
                  setEditedContent(content)
                }
              }}
              rows={3}
              autoFocus
              className="w-full resize-none border-0 bg-transparent text-[15px] text-foreground outline-none"
            />
            <div className="mt-2 flex justify-end gap-1">
              <button
                type="button"
                title="Cancel"
                onClick={() => {
                  setIsEditing(false)
                  setEditedContent(content)
                }}
                className="inline-flex h-7 w-7 items-center justify-center rounded-md text-muted-foreground hover:bg-background hover:text-foreground"
              >
                <Undo2 className="h-3.5 w-3.5" />
              </button>
              <button
                type="button"
                title="Save"
                onClick={handleSaveEdit}
                className="inline-flex h-7 w-7 items-center justify-center rounded-md text-primary hover:bg-background"
              >
                <Save className="h-3.5 w-3.5" />
              </button>
            </div>
          </div>
        </div>
      )
    }

    const { preview, remainder } = previewUserMessageText(
      displayContent,
      USER_PREVIEW_MAX_WORDS
    )

    return (
      <div
        className={cn(
          "group mb-4 flex min-w-0 w-full items-center justify-end gap-1",
          className
        )}
      >
        {editable && onEdit && (
          <button
            type="button"
            title="Edit message"
            onClick={() => setIsEditing(true)}
            className="inline-flex h-7 w-7 items-center justify-center rounded-md text-muted-foreground opacity-0 transition hover:bg-muted hover:text-foreground group-hover:opacity-100"
          >
            <Pencil className="h-3.5 w-3.5" />
          </button>
        )}
        <div
          className={cn(
            "max-w-[70%] min-w-0 rounded-[18px] px-4 py-2.5 text-[15px] leading-relaxed break-words whitespace-pre-wrap text-foreground",
            contentClassName
          )}
          style={{ background: "var(--user-bubble)" }}
        >
          {remainder && !longPromptExpanded ? preview : displayContent}
          {remainder ? (
            <button
              type="button"
              className="mt-2 block w-full rounded-md py-1 text-left text-[13px] font-medium text-primary underline-offset-2 hover:underline"
              aria-expanded={longPromptExpanded}
              onClick={() => setLongPromptExpanded((v) => !v)}
            >
              {longPromptExpanded ? "Show less" : "Show more"}
            </button>
          ) : null}
        </div>
      </div>
    )
  }

  return (
    <div className={cn("group mb-[var(--density-msg-gap)]", className)}>
      <div
        className={cn(
          "max-w-full text-[15px] leading-[var(--density-line)] text-foreground",
          contentClassName
        )}
      >
        {reasoning ? (
          <MessageReasoning
            defaultOpen={reasoningDefaultOpen}
            duration={reasoningDuration}
          >
            {reasoning}
          </MessageReasoning>
        ) : null}

        {tools.length > 0 ? <MessageToolCalls tools={tools} /> : null}

        {displayContent ? (
          <div className="lc-markdown max-w-none">
            <ReactMarkdown components={markdownComponents}>
              {displayContent}
            </ReactMarkdown>
          </div>
        ) : null}

        {codeBlocks.map((block, i) => (
          <MessageCode key={`${block.language ?? "code"}-${i}`} block={block} />
        ))}

        {artifacts.map((artifact) => (
          <MessageArtifact key={artifact.id} artifact={artifact} />
        ))}

        {(insideButtons.length > 0 ||
          outsideButtons.length > 0 ||
          (editable && onEdit)) && (
          <div className="mt-2 flex flex-wrap items-center gap-1 opacity-0 transition group-hover:opacity-100">
            {[...insideButtons, ...outsideButtons].map((button) => (
              <button
                key={button.id}
                type="button"
                title={button.title}
                onClick={button.onClick}
                className={cn(
                  "inline-flex h-7 w-7 items-center justify-center rounded-md text-muted-foreground hover:bg-muted hover:text-foreground",
                  button.className
                )}
              >
                {button.icon}
              </button>
            ))}
            {editable && onEdit && (
              <button
                type="button"
                title="Edit message"
                onClick={() => setIsEditing(true)}
                className="inline-flex h-7 w-7 items-center justify-center rounded-md text-muted-foreground hover:bg-muted hover:text-foreground"
              >
                <Pencil className="h-3.5 w-3.5" />
              </button>
            )}
          </div>
        )}
      </div>
    </div>
  )
}

export type {
  MessageArtifactData,
  MessageCodeBlockData,
  MessageToolCallData,
} from "@/components/ui/message-parts"
export {
  MessageArtifact,
  MessageCode,
  MessageReasoning,
  MessageToolCall,
  MessageToolCalls,
} from "@/components/ui/message-parts"

"use client"

import {
  Brain,
  Check,
  ChevronDown,
  Copy,
  FileText,
  Loader2,
  Table2,
  TriangleAlert,
} from "lucide-react"
import { useTheme } from "next-themes"
import { useEffect, useState } from "react"
import ReactMarkdown from "react-markdown"
import { codeToHtml } from "shiki"

import {
  Collapsible,
  CollapsibleContent,
  CollapsibleTrigger,
} from "@/components/ui/collapsible"
import { cn } from "@/lib/utils"

export type MessageToolCallData = {
  id: string
  name: string
  status?: "pending" | "running" | "done" | "error"
  input?: string
  output?: string
}

export type MessageCodeBlockData = {
  language?: string
  code: string
  title?: string
}

export type MessageArtifactData = {
  id: string
  title: string
  kind?: "file" | "table" | "chart" | "text" | string
  summary?: string
  content?: string
  onOpen?: () => void
}

export function MessageReasoning({
  children,
  defaultOpen = false,
  duration,
  className,
}: {
  children: string
  defaultOpen?: boolean
  duration?: number
  className?: string
}) {
  const [open, setOpen] = useState(defaultOpen)
  const label =
    duration == null
      ? "Thought for a few seconds"
      : `Thought for ${duration} seconds`

  return (
    <Collapsible
      open={open}
      onOpenChange={setOpen}
      className={cn("lc-reveal mb-2", className)}
    >
      <CollapsibleTrigger asChild>
        <button
          type="button"
          className="flex w-full items-center gap-1.5 py-0.5 text-left text-[13px] text-muted-foreground transition-colors hover:text-foreground"
        >
          <Brain className="h-3.5 w-3.5 shrink-0 opacity-70" />
          <span className="min-w-0 flex-1">{label}</span>
          <ChevronDown
            className={cn(
              "h-3.5 w-3.5 shrink-0 opacity-50 transition-transform",
              open && "rotate-180"
            )}
          />
        </button>
      </CollapsibleTrigger>
      <CollapsibleContent>
        <div
          className="mt-2 border-l pl-3 text-[13px] leading-relaxed text-muted-foreground"
          style={{ borderColor: "var(--border)" }}
        >
          <ReactMarkdown>{children}</ReactMarkdown>
        </div>
      </CollapsibleContent>
    </Collapsible>
  )
}

function toolVerb(status: NonNullable<MessageToolCallData["status"]>) {
  if (status === "running" || status === "pending") return "Running"
  if (status === "error") return "Failed"
  return "Ran"
}

/** Single Cursor-style tool row — no card chrome. */
export function MessageToolCall({
  tool,
  defaultOpen = false,
  className,
}: {
  tool: MessageToolCallData
  defaultOpen?: boolean
  className?: string
}) {
  const [open, setOpen] = useState(defaultOpen)
  const status = tool.status ?? "done"
  const running = status === "running" || status === "pending"
  const errored = status === "error"
  const hasBody = !!(tool.input || tool.output)

  return (
    <Collapsible
      open={open}
      onOpenChange={setOpen}
      className={cn("lc-reveal group", className)}
    >
      <CollapsibleTrigger asChild>
        <button
          type="button"
          disabled={!hasBody}
          className={cn(
            "flex w-full items-center gap-1.5 py-[3px] text-left text-[13px] leading-snug",
            hasBody
              ? "cursor-pointer text-muted-foreground hover:text-foreground"
              : "cursor-default text-muted-foreground"
          )}
        >
          {running ? (
            <Loader2 className="h-3 w-3 shrink-0 animate-spin opacity-70" />
          ) : errored ? (
            <TriangleAlert className="h-3 w-3 shrink-0 text-destructive" />
          ) : null}
          <span className="shrink-0">{toolVerb(status)}</span>
          <span
            className="min-w-0 truncate font-medium"
            style={{
              color: errored ? "var(--destructive)" : "var(--ink)",
              opacity: 0.88,
            }}
          >
            {tool.name}
          </span>
          {!open &&
          tool.output &&
          tool.output.length < 28 &&
          !tool.output.includes("\n") ? (
            <span
              className="shrink-0 text-[12px]"
              style={{
                color: tool.output.startsWith("+")
                  ? "oklch(0.62 0.15 155)"
                  : "var(--ink-3)",
              }}
            >
              {tool.output}
            </span>
          ) : null}
          {hasBody ? (
            <ChevronDown
              className={cn(
                "ml-auto h-3 w-3 shrink-0 opacity-0 transition group-hover:opacity-40",
                open && "rotate-180 opacity-40"
              )}
            />
          ) : null}
        </button>
      </CollapsibleTrigger>
      {hasBody ? (
        <CollapsibleContent>
          <div className="mb-1.5 ml-0.5 space-y-1.5 border-l pl-3" style={{ borderColor: "var(--border)" }}>
            {tool.input ? (
              <pre
                className="m-0 overflow-x-auto py-1 text-[12px] leading-relaxed whitespace-pre-wrap break-words text-muted-foreground"
                style={{ fontFamily: "var(--font-mono)" }}
              >
                {tool.input}
              </pre>
            ) : null}
            {tool.output ? (
              <pre
                className="m-0 overflow-x-auto py-1 text-[12px] leading-relaxed whitespace-pre-wrap break-words"
                style={{
                  fontFamily: "var(--font-mono)",
                  color: "var(--ink-2)",
                }}
              >
                {tool.output}
              </pre>
            ) : null}
          </div>
        </CollapsibleContent>
      ) : null}
    </Collapsible>
  )
}

/** Stack of minimal tool rows; collapses behind “Used N tools” when many. */
export function MessageToolCalls({
  tools,
  className,
  collapseAt = 3,
  defaultOpen,
}: {
  tools: MessageToolCallData[]
  className?: string
  /** Collapse the list behind a summary when tool count ≥ this. */
  collapseAt?: number
  defaultOpen?: boolean
}) {
  const many = tools.length >= collapseAt
  const [open, setOpen] = useState(defaultOpen ?? !many)

  if (tools.length === 0) return null

  const list = (
    <div className="flex flex-col">
      {tools.map((tool) => (
        <MessageToolCall key={tool.id} tool={tool} />
      ))}
    </div>
  )

  if (!many) {
    return <div className={cn("mb-3", className)}>{list}</div>
  }

  return (
    <Collapsible
      open={open}
      onOpenChange={setOpen}
      className={cn("lc-reveal mb-3", className)}
    >
      <CollapsibleTrigger asChild>
        <button
          type="button"
          className="flex w-full items-center gap-1.5 py-0.5 text-left text-[13px] text-muted-foreground transition-colors hover:text-foreground"
        >
          <span>
            Used {tools.length} tool{tools.length === 1 ? "" : "s"}
          </span>
          <ChevronDown
            className={cn(
              "h-3.5 w-3.5 opacity-50 transition-transform",
              open && "rotate-180"
            )}
          />
        </button>
      </CollapsibleTrigger>
      <CollapsibleContent>{list}</CollapsibleContent>
    </Collapsible>
  )
}

const SHIKI_LANGS = new Set([
  "ts",
  "tsx",
  "js",
  "jsx",
  "typescript",
  "javascript",
  "json",
  "python",
  "py",
  "bash",
  "shell",
  "sh",
  "css",
  "html",
  "md",
  "markdown",
  "sql",
  "yaml",
  "yml",
  "toml",
  "rust",
  "go",
  "java",
  "c",
  "cpp",
  "text",
  "plaintext",
])

function normalizeLang(lang?: string) {
  if (!lang) return "text"
  const l = lang.toLowerCase().trim()
  if (l === "typescript") return "ts"
  if (l === "javascript") return "js"
  if (l === "python") return "py"
  if (l === "shell" || l === "zsh") return "bash"
  return SHIKI_LANGS.has(l) ? l : "text"
}

function HighlightedCode({
  code,
  language,
}: {
  code: string
  language?: string
}) {
  const { resolvedTheme } = useTheme()
  const [html, setHtml] = useState<string | null>(null)
  const lang = normalizeLang(language)

  useEffect(() => {
    let cancelled = false
    const theme = resolvedTheme === "dark" ? "github-dark" : "github-light"
    void codeToHtml(code, { lang, theme })
      .then((out) => {
        if (!cancelled) setHtml(out)
      })
      .catch(() => {
        if (!cancelled) setHtml(null)
      })
    return () => {
      cancelled = true
    }
  }, [code, lang, resolvedTheme])

  if (!html) {
    return (
      <pre
        className="m-0 overflow-x-auto px-3.5 py-3 text-[12.5px] leading-[1.55]"
        style={{
          background: "var(--code-bg)",
          color: "var(--code-ink)",
          fontFamily: "var(--font-mono)",
        }}
      >
        <code>{code}</code>
      </pre>
    )
  }

  return (
    <div
      className="lc-code-shiki overflow-x-auto text-[12.5px] leading-[1.55] [&_pre]:m-0 [&_pre]:!bg-transparent [&_pre]:px-3.5 [&_pre]:py-3 [&_code]:font-mono"
      style={{ background: "var(--code-bg)" }}
      dangerouslySetInnerHTML={{ __html: html }}
    />
  )
}

export function MessageCode({
  block,
  className,
}: {
  block: MessageCodeBlockData
  className?: string
}) {
  const [copied, setCopied] = useState(false)
  const copy = async () => {
    try {
      await navigator.clipboard.writeText(block.code)
      setCopied(true)
      window.setTimeout(() => setCopied(false), 1200)
    } catch {
      /* ignore */
    }
  }
  const lang = normalizeLang(block.language)
  const langLabel = (block.language ?? lang).toLowerCase()

  return (
    <div
      className={cn("lc-reveal my-3 overflow-hidden rounded-lg", className)}
      style={{
        border: "1px solid var(--border)",
        background: "var(--code-bg)",
      }}
    >
      <div
        className="flex items-center gap-2 px-3 py-1.5"
        style={{
          borderBottom: "1px solid var(--border)",
          background: "color-mix(in oklab, var(--code-bg) 70%, var(--bg-soft))",
        }}
      >
        <span
          className="rounded px-1.5 py-0.5 text-[11px] font-medium uppercase tracking-wide"
          style={{
            color: "var(--ink-2)",
            background: "var(--bg-soft)",
            border: "1px solid var(--border)",
            fontFamily: "var(--font-mono)",
          }}
        >
          {langLabel}
        </span>
        {block.title ? (
          <span
            className="min-w-0 flex-1 truncate text-[12px]"
            style={{
              color: "var(--ink-3)",
              fontFamily: "var(--font-mono)",
            }}
          >
            {block.title}
          </span>
        ) : (
          <span className="flex-1" />
        )}
        <button
          type="button"
          onClick={() => void copy()}
          className="inline-flex h-6 w-6 items-center justify-center rounded-md text-muted-foreground transition hover:bg-muted hover:text-foreground"
          title={copied ? "Copied" : "Copy"}
        >
          {copied ? (
            <Check className="h-3.5 w-3.5" />
          ) : (
            <Copy className="h-3.5 w-3.5" />
          )}
        </button>
      </div>
      <HighlightedCode code={block.code} language={block.language} />
    </div>
  )
}

function artifactIcon(kind?: string) {
  if (kind === "table") return <Table2 className="h-4 w-4" />
  return <FileText className="h-4 w-4" />
}

export function MessageArtifact({
  artifact,
  className,
}: {
  artifact: MessageArtifactData
  className?: string
}) {
  const meta = [artifact.kind, artifact.summary].filter(Boolean).join(" · ")

  return (
    <div
      className={cn("lc-reveal my-3 overflow-hidden rounded-xl", className)}
      style={{
        border: "1px solid var(--border)",
        background: "var(--surface)",
      }}
    >
      <button
        type="button"
        onClick={artifact.onOpen}
        className="flex w-full items-center gap-2.5 px-3.5 py-2 text-left transition hover:opacity-90"
        style={{
          background: "var(--bg-soft)",
          borderBottom: artifact.content ? "1px solid var(--border)" : undefined,
          cursor: artifact.onOpen ? "pointer" : "default",
        }}
      >
        <span
          className="inline-flex shrink-0"
          style={{ color: "var(--primary)" }}
        >
          {artifactIcon(artifact.kind)}
        </span>
        <div className="min-w-0 flex-1">
          <div
            className="truncate text-[13px] font-medium"
            style={{ color: "var(--ink)" }}
          >
            {artifact.title}
          </div>
          {meta ? (
            <div
              className="mt-0.5 truncate text-[11.5px]"
              style={{ color: "var(--ink-3)" }}
            >
              {meta}
            </div>
          ) : null}
        </div>
      </button>
      {artifact.content ? (
        <div
          className="max-h-[min(14rem,40vh)] overflow-auto px-3.5 py-2.5 text-[12.5px] leading-relaxed whitespace-pre-wrap break-words"
          style={{
            background: "var(--code-bg)",
            color: "var(--code-ink)",
            fontFamily: "var(--font-mono)",
          }}
        >
          {artifact.content}
        </div>
      ) : null}
    </div>
  )
}
